package dev.aura.player;
import java.util.*;
final class TrackOrder {
 static final String[] IDS={"track","title","artist","album","duration","stored"},LABELS={"트랙 번호","제목","아티스트","앨범","재생 시간","저장 순서"};
 static int number(String raw){try{String value=raw.trim().split("/",2)[0].trim();int n=Integer.parseInt(value);return Math.max(0,n);}catch(Exception ignored){return 0;}}
 private static final java.util.regex.Pattern DISC_FILE=java.util.regex.Pattern.compile("^(?:\\[|\\()?([0-9]{1,2})[-_.]([0-9]{1,3})(?:[^0-9]|$)"),TRACK_FILE=java.util.regex.Pattern.compile("^(?:\\[|\\()?([0-9]{1,3})(?:[\\s._)\\]\\-]|$)");
 static int[] fileNumbers(String uri){String name=Objects.toString(android.net.Uri.parse(uri).getLastPathSegment(),"");int slash=name.lastIndexOf('/');if(slash>=0)name=name.substring(slash+1);var disc=DISC_FILE.matcher(name);if(disc.find())return new int[]{number(disc.group(1)),number(disc.group(2))};var track=TRACK_FILE.matcher(name);return new int[]{0,track.find()?number(track.group(1)):0};}
 static int natural(String left,String right){int i=0,j=0;while(i<left.length()&&j<right.length()){char a=left.charAt(i),b=right.charAt(j);if(a>='0'&&a<='9'&&b>='0'&&b<='9'){int ae=i,be=j;while(ae<left.length()&&Character.isDigit(left.charAt(ae)))ae++;while(be<right.length()&&Character.isDigit(right.charAt(be)))be++;int az=i,bz=j;while(az<ae&&left.charAt(az)=='0')az++;while(bz<be&&right.charAt(bz)=='0')bz++;int length=Integer.compare(ae-az,be-bz);if(length!=0)return length;for(int k=0;k<ae-az;k++){int c=Character.compare(left.charAt(az+k),right.charAt(bz+k));if(c!=0)return c;}i=ae;j=be;continue;}int c=Character.compare(Character.toLowerCase(a),Character.toLowerCase(b));if(c!=0)return c;i++;j++;}return Integer.compare(left.length()-i,right.length()-j);}
 static String label(String mode){for(int i=0;i<IDS.length;i++)if(IDS[i].equals(mode))return LABELS[i];return LABELS[0];}
 static List<Track> sorted(List<Track> tracks,String mode,boolean descending){List<Track> out=new ArrayList<>(tracks);if(mode.equals("stored")){if(descending)Collections.reverse(out);return out;}Comparator<Track> order=switch(mode){case "title"->Comparator.comparing(t->t.sortTitle,TrackOrder::natural);case "artist"->Comparator.comparing(t->t.artist,TrackOrder::natural);case "album"->Comparator.comparing(t->t.album,TrackOrder::natural);case "duration"->Comparator.comparingLong(t->t.duration);default->Comparator.<Track>comparingInt(t->t.orderDisc>0?t.orderDisc:1).thenComparingInt(t->t.orderTrack);};order=order.thenComparing(t->t.sortTitle,TrackOrder::natural).thenComparing(t->t.uri);if(descending)order=order.reversed();if(mode.equals("track"))order=Comparator.<Track>comparingInt(t->t.orderTrack>0?0:1).thenComparing(order);out.sort(order);return out;}
}
